"""
codebench_blend_view — turn a Blender scene into a self-contained, INTERACTIVE
WebGL 3D viewer for CodeBench's preview pane.
══════════════════════════════════════════════════════════════════════════════

CodeBench's preview pane renders any ``[plot saved] <file.html>`` path inside a
``WKWebView`` (JavaScript enabled, WebGL on by default) — the same channel the
plotly charts use. This module exploits that to ship a *live, orbitable* 3D
model instead of a flat render:

    * geometry is extracted from the evaluated scene (modifiers applied),
    * baked to world space and packed as base64 Float32 buffers,
    * embedded in a stand-alone HTML page with a hand-written WebGL viewer
      (orbit / pinch-zoom / two-finger-pan, touch-first for iPad),
    * NO external JS — works fully offline.

A Cycles render (if provided) is embedded too, behind a "Rendered ⟷ 3D" toggle,
so the showcase keeps the photoreal image *and* gains interactivity.

Public API
──────────
    build_view(scene, render_png_path=None, title="scene") -> str | None
        Build the viewer HTML, write it under ~/Documents/ToolOutputs, return
        its path (or None if the scene had no drawable geometry).

    emit(path) -> None
        Fire every CodeBench preview channel for `path` (`[plot saved]` stdout
        marker + __main__.__codebench_plot_path + preview_request.txt).
"""

import os
import sys
import json
import base64
import tempfile
import time
from array import array

# Cap so a heavy subdiv scene can't produce a 50 MB HTML. Above this we keep
# every Nth triangle (crude decimation — preview only, never touches the scene).
_TRI_BUDGET = 220_000
_FALLBACK_COLOR = (0.78, 0.78, 0.82)


# ─── geometry extraction ───────────────────────────────────────────────────

def _material_color(mat):
    """Best-effort base color (linear RGB) for a material."""
    if mat is None:
        return _FALLBACK_COLOR
    try:
        if getattr(mat, "use_nodes", False) and mat.node_tree:
            nodes = mat.node_tree.nodes
            # Prefer the active output's surface shader; fall back to scanning.
            for ntype, sock in (("BSDF_PRINCIPLED", "Base Color"),
                                 ("BSDF_DIFFUSE", "Color"),
                                 ("EMISSION", "Color"),
                                 ("BSDF_GLOSSY", "Color")):
                for node in nodes:
                    if node.type == ntype:
                        inp = node.inputs.get(sock)
                        if inp is not None and hasattr(inp, "default_value"):
                            c = inp.default_value
                            return (float(c[0]), float(c[1]), float(c[2]))
        c = mat.diffuse_color
        return (float(c[0]), float(c[1]), float(c[2]))
    except Exception:
        return _FALLBACK_COLOR


def _f32_b64(vals):
    """Pack a flat list of floats as little-endian Float32 → base64 (matches
    JS `Float32Array`). `array` is far faster than struct.pack(*millions)."""
    a = array("f", vals)
    if sys.byteorder != "little":
        a.byteswap()
    return base64.b64encode(a.tobytes()).decode("ascii")


def _iter_drawable(scene):
    """Yield objects that can produce a renderable mesh. Uses `hide_render`
    (data-level, no context needed) — `visible_get()` can fail in a handler."""
    for obj in scene.objects:
        if obj.type in {'MESH', 'CURVE', 'SURFACE', 'FONT', 'META'} and not obj.hide_render:
            yield obj


def _extract_geometry(scene):
    """Return (objects, bbox_min, bbox_max, stats).

    Each object dict: {name, color:[r,g,b], count:int, p:b64, n:b64} where p/n
    are packed little-endian Float32 triangle-soup buffers (world space)."""
    import bpy
    try:
        depsgraph = bpy.context.evaluated_depsgraph_get()
    except Exception:
        depsgraph = None

    # First pass: collect meshes + total triangle count (for decimation stride).
    collected = []
    total_tris = 0
    for obj in _iter_drawable(scene):
        try:
            src = obj.evaluated_get(depsgraph) if depsgraph is not None else obj
            me = src.to_mesh()
        except Exception:
            continue
        if me is None:
            continue
        try:
            me.calc_loop_triangles()
        except Exception:
            try:
                src.to_mesh_clear()
            except Exception:
                pass
            continue
        ntri = len(me.loop_triangles)
        if ntri == 0:
            try:
                src.to_mesh_clear()
            except Exception:
                pass
            continue
        collected.append((obj, src, me, ntri))
        total_tris += ntri

    stride = 1
    if total_tris > _TRI_BUDGET:
        stride = (total_tris // _TRI_BUDGET) + 1

    objects = []
    bmin = [float("inf")] * 3
    bmax = [float("-inf")] * 3
    kept_tris = 0
    for obj, src, me, ntri in collected:
        mw = obj.matrix_world
        try:
            nmat = mw.to_3x3().inverted_safe().transposed()
        except Exception:
            nmat = mw.to_3x3()
        verts = me.vertices
        pos = []
        nor = []
        for ti, tri in enumerate(me.loop_triangles):
            if stride > 1 and (ti % stride):
                continue
            smooth = tri.use_smooth
            fn = nmat @ tri.normal
            for vi in tri.vertices:
                v = verts[vi]
                co = mw @ v.co
                n = (nmat @ v.normal) if smooth else fn
                pos.append(co.x); pos.append(co.y); pos.append(co.z)
                nor.append(n.x);  nor.append(n.y);  nor.append(n.z)
                if co.x < bmin[0]: bmin[0] = co.x
                if co.y < bmin[1]: bmin[1] = co.y
                if co.z < bmin[2]: bmin[2] = co.z
                if co.x > bmax[0]: bmax[0] = co.x
                if co.y > bmax[1]: bmax[1] = co.y
                if co.z > bmax[2]: bmax[2] = co.z
        try:
            src.to_mesh_clear()
        except Exception:
            pass
        if not pos:
            continue
        kept_tris += len(pos) // 9
        col = _material_color(obj.material_slots[0].material) if obj.material_slots else _FALLBACK_COLOR
        objects.append({
            "name": obj.name,
            "color": [round(c, 4) for c in col],
            "count": len(pos) // 3,
            "p": _f32_b64(pos),
            "n": _f32_b64(nor),
        })

    if not objects:
        return [], [0, 0, 0], [0, 0, 0], {}

    stats = {
        "objects": len(objects),
        "triangles": kept_tris,
        "decimated": stride > 1,
        "stride": stride,
    }
    return objects, [round(v, 5) for v in bmin], [round(v, 5) for v in bmax], stats


# ─── HTML assembly ──────────────────────────────────────────────────────────

def _data_uri(png_path):
    if not png_path or not os.path.isfile(png_path):
        return None
    try:
        with open(png_path, "rb") as f:
            return "data:image/png;base64," + base64.b64encode(f.read()).decode("ascii")
    except Exception:
        return None


def build_view(scene, render_png_path=None, title="scene"):
    """Build the interactive viewer HTML; return its path (or None)."""
    objects, bmin, bmax, stats = _extract_geometry(scene)
    if not objects:
        return None

    data = {
        "title": title,
        "objects": objects,
        "bbox": {"min": bmin, "max": bmax},
        "stats": stats,
        "render": _data_uri(render_png_path),
    }
    html = _TEMPLATE.replace("__DATA__", json.dumps(data, separators=(",", ":")))

    out_dir = os.path.expanduser("~/Documents/ToolOutputs")
    try:
        os.makedirs(out_dir, exist_ok=True)
    except OSError:
        out_dir = tempfile.gettempdir()
    stem = os.path.splitext(os.path.basename(title))[0] or "scene"
    out_path = os.path.join(out_dir, "%s_%d.view.html" % (stem, int(time.time() * 1000)))
    tmp = out_path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        f.write(html)
    os.replace(tmp, out_path)
    return out_path


def emit(path):
    """Fire every CodeBench preview channel for `path`."""
    if not path:
        return
    print("[plot saved] %s" % path, flush=True)
    try:
        sys.modules["__main__"].__codebench_plot_path = path
    except Exception:
        pass
    try:
        d = os.path.join(tempfile.gettempdir(), "latex_signals")
        os.makedirs(d, exist_ok=True)
        with open(os.path.join(d, "preview_request.txt"), "w", encoding="utf-8") as f:
            f.write(path)
    except Exception:
        pass


# ─── the self-contained viewer (HTML + hand-written WebGL, no deps) ─────────
# Single placeholder __DATA__ → a JSON blob {title,objects,bbox,stats,render}.
# Geometry is base64 Float32 triangle soup in WORLD space; model matrix is
# identity so normals are already world-space. Blender is Z-up; the camera math
# honours that (up = +Z).

_TEMPLATE = r"""<!doctype html><html lang=en><head>
<meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no">
<meta name=color-scheme content=dark><title>3D preview</title><style>
:root{--accent:#a855f7;--accent2:#6366f1;--fg:#f0f0f5;--fg2:#a8a8b8}
*{box-sizing:border-box;-webkit-user-select:none;user-select:none;-webkit-tap-highlight-color:transparent}
html,body{margin:0;height:100%;overflow:hidden;background:#0a0a0f;
font:13px/1.4 -apple-system,SF Pro,sans-serif;color:var(--fg)}
#wrap{position:fixed;inset:0;background:radial-gradient(120% 120% at 50% 0%,#15151f 0%,#0a0a0f 60%,#06060a 100%)}
canvas{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}
#shot{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;background:#000;display:none}
#hud{position:absolute;left:12px;top:10px;pointer-events:none;text-shadow:0 1px 3px #000}
#hud .t{font-weight:600;color:#fff;font-size:14px}
#hud .s{color:var(--fg2);font-size:11px;margin-top:2px}
#tip{position:absolute;left:0;right:0;bottom:10px;text-align:center;color:var(--fg2);
font-size:11px;pointer-events:none;text-shadow:0 1px 3px #000;transition:opacity .6s;opacity:.9}
.bar{position:absolute;right:10px;top:10px;display:flex;gap:6px}
.bar button{pointer-events:auto;background:rgba(30,30,46,.72);color:var(--fg);border:1px solid #2a2a42;
border-radius:9px;padding:7px 11px;font:12px/1 -apple-system,sans-serif;backdrop-filter:blur(8px);
-webkit-backdrop-filter:blur(8px)}
.bar button:active{background:var(--accent2)}
.bar button.on{background:var(--accent);border-color:var(--accent);color:#fff}
#err{position:absolute;inset:0;display:none;align-items:center;justify-content:center;
padding:24px;text-align:center;color:#fbbf24}
</style></head><body><div id=wrap>
<canvas id=gl></canvas>
<img id=shot alt="rendered">
<div id=hud><div class=t id=ttl></div><div class=s id=sub></div></div>
<div class=bar>
  <button id=spin class=on title="auto-rotate">⟳</button>
  <button id=reset title="reset view">⤢</button>
  <button id=mode title="rendered / 3D" style="display:none">Rendered</button>
</div>
<div id=tip>drag to orbit · pinch to zoom · two-finger drag to pan</div>
<div id=err></div></div>
<script>
"use strict";
var SCENE=__DATA__;
function $(id){return document.getElementById(id);}
function fail(m){$("err").style.display="flex";$("err").textContent="⚠️ "+m;$("gl").style.display="none";}

function b64f32(b64){var s=atob(b64),n=s.length,a=new Uint8Array(n);for(var i=0;i<n;i++)a[i]=s.charCodeAt(i);return new Float32Array(a.buffer);}
function sub(a,b){return[a[0]-b[0],a[1]-b[1],a[2]-b[2]];}
function add(a,b){return[a[0]+b[0],a[1]+b[1],a[2]+b[2]];}
function dot(a,b){return a[0]*b[0]+a[1]*b[1]+a[2]*b[2];}
function cross(a,b){return[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];}
function nrm(a){var l=Math.hypot(a[0],a[1],a[2])||1;return[a[0]/l,a[1]/l,a[2]/l];}
function mul(a,b){var o=new Float32Array(16);for(var c=0;c<4;c++)for(var r=0;r<4;r++){var s=0;for(var k=0;k<4;k++)s+=a[k*4+r]*b[c*4+k];o[c*4+r]=s;}return o;}
function persp(fy,as,n,f){var t=1/Math.tan(fy/2);return new Float32Array([t/as,0,0,0, 0,t,0,0, 0,0,(f+n)/(n-f),-1, 0,0,2*f*n/(n-f),0]);}
function look(e,c,u){var z=nrm(sub(e,c)),x=nrm(cross(u,z)),y=cross(z,x);
return new Float32Array([x[0],y[0],z[0],0, x[1],y[1],z[1],0, x[2],y[2],z[2],0, -dot(x,e),-dot(y,e),-dot(z,e),1]);}

var cv=$("gl");
var gl=cv.getContext("webgl",{antialias:true,alpha:false,preserveDrawingBuffer:false})||cv.getContext("experimental-webgl");
if(!gl){fail("WebGL is unavailable in this preview.");}

function sh(t,src){var s=gl.createShader(t);gl.shaderSource(s,src);gl.compileShader(s);
if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw gl.getShaderInfoLog(s);return s;}
function prog(v,f){var p=gl.createProgram();gl.attachShader(p,sh(gl.VERTEX_SHADER,v));
gl.attachShader(p,sh(gl.FRAGMENT_SHADER,f));gl.linkProgram(p);
if(!gl.getProgramParameter(p,gl.LINK_STATUS))throw gl.getProgramInfoLog(p);return p;}

var P,Pg,objs=[],grid=null;
try{
P=prog(
"attribute vec3 aPos;attribute vec3 aNor;uniform mat4 uMVP;varying vec3 vN;varying vec3 vP;"+
"void main(){vN=aNor;vP=aPos;gl_Position=uMVP*vec4(aPos,1.0);}",
"precision highp float;varying vec3 vN;varying vec3 vP;uniform vec3 uColor;uniform vec3 uEye;"+
"void main(){vec3 N=normalize(vN);vec3 V=normalize(uEye-vP);if(dot(N,V)<0.0)N=-N;"+
"vec3 L1=normalize(vec3(0.45,0.35,0.92));vec3 L2=normalize(vec3(-0.6,-0.25,0.35));"+
"float d1=max(dot(N,L1),0.0);float d2=max(dot(N,L2),0.0)*0.4;"+
"float amb=0.34+0.26*(N.z*0.5+0.5);vec3 c=uColor*(amb+d1*0.85+d2);"+
"c+=pow(1.0-max(dot(N,V),0.0),3.0)*0.22;c=pow(clamp(c,0.0,1.0),vec3(0.4545));"+
"gl_FragColor=vec4(c,1.0);}");
Pg=prog(
"attribute vec3 aPos;uniform mat4 uMVP;varying float vF;uniform vec3 uC;"+
"void main(){vF=clamp(1.0-length(aPos.xy-uC.xy)/uC.z,0.0,1.0);gl_Position=uMVP*vec4(aPos,1.0);}",
"precision mediump float;varying float vF;void main(){gl_FragColor=vec4(0.40,0.40,0.55,vF*0.34);}");

for(var i=0;i<SCENE.objects.length;i++){var o=SCENE.objects[i];
 var pb=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,pb);gl.bufferData(gl.ARRAY_BUFFER,b64f32(o.p),gl.STATIC_DRAW);
 var nb=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,nb);gl.bufferData(gl.ARRAY_BUFFER,b64f32(o.n),gl.STATIC_DRAW);
 objs.push({pb:pb,nb:nb,count:o.count,color:o.color});}
}catch(e){fail("shader/buffer error: "+e);}

// ── camera framing from bbox (Z-up) ──
var mn=SCENE.bbox.min,mx=SCENE.bbox.max;
var ctr=[(mn[0]+mx[0])/2,(mn[1]+mx[1])/2,(mn[2]+mx[2])/2];
var diag=Math.hypot(mx[0]-mn[0],mx[1]-mn[1],mx[2]-mn[2])||2;
var cam={az:0.8,el:0.52,r:diag*1.45,tx:ctr[0],ty:ctr[1],tz:ctr[2]};
var R0={az:0.8,el:0.52,r:diag*1.45,tx:ctr[0],ty:ctr[1],tz:ctr[2]};
var spin=true,interacted=false;

// ── grid on the floor (z = bbox bottom) ──
(function(){try{
var step=diag/10,half=diag*0.9,z=mn[2],g=[];
for(var t=-10;t<=10;t++){var d=t*step;
 g.push(ctr[0]-half,ctr[1]+d,z, ctr[0]+half,ctr[1]+d,z);
 g.push(ctr[0]+d,ctr[1]-half,z, ctr[0]+d,ctr[1]+half,z);}
var gb=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,gb);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(g),gl.STATIC_DRAW);
grid={b:gb,count:g.length/3,c:[ctr[0],ctr[1],half*1.1]};
}catch(e){grid=null;}})();

function eyePos(){var ce=Math.cos(cam.el),se=Math.sin(cam.el),ca=Math.cos(cam.az),sa=Math.sin(cam.az);
return[cam.tx+cam.r*ce*ca, cam.ty+cam.r*ce*sa, cam.tz+cam.r*se];}

var DPR=Math.min(window.devicePixelRatio||1,2);
function resize(){var w=cv.clientWidth|0,h=cv.clientHeight|0;
 if(cv.width!==w*DPR||cv.height!==h*DPR){cv.width=w*DPR;cv.height=h*DPR;}}

function draw(){
 if(!gl)return;
 resize();
 gl.viewport(0,0,cv.width,cv.height);
 gl.clearColor(0.043,0.043,0.063,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);
 gl.enable(gl.DEPTH_TEST);
 if(spin&&!interacted)cam.az+=0.0045;
 var eye=eyePos();
 var asp=cv.width/Math.max(cv.height,1);
 var V=look(eye,[cam.tx,cam.ty,cam.tz],[0,0,1]);
 var Pm=persp(0.86,asp,diag*0.02,diag*12+10);
 var MVP=mul(Pm,V);
 // grid (blended, no depth write)
 if(grid){gl.useProgram(Pg);gl.enable(gl.BLEND);gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);gl.depthMask(false);
  var la=gl.getAttribLocation(Pg,"aPos");gl.bindBuffer(gl.ARRAY_BUFFER,grid.b);
  gl.enableVertexAttribArray(la);gl.vertexAttribPointer(la,3,gl.FLOAT,false,0,0);
  gl.uniformMatrix4fv(gl.getUniformLocation(Pg,"uMVP"),false,MVP);
  gl.uniform3fv(gl.getUniformLocation(Pg,"uC"),grid.c);
  gl.drawArrays(gl.LINES,0,grid.count);gl.depthMask(true);gl.disable(gl.BLEND);}
 // meshes
 gl.useProgram(P);
 var aP=gl.getAttribLocation(P,"aPos"),aN=gl.getAttribLocation(P,"aNor");
 gl.uniformMatrix4fv(gl.getUniformLocation(P,"uMVP"),false,MVP);
 gl.uniform3fv(gl.getUniformLocation(P,"uEye"),eye);
 var uC=gl.getUniformLocation(P,"uColor");
 for(var i=0;i<objs.length;i++){var o=objs[i];
  gl.bindBuffer(gl.ARRAY_BUFFER,o.pb);gl.enableVertexAttribArray(aP);gl.vertexAttribPointer(aP,3,gl.FLOAT,false,0,0);
  gl.bindBuffer(gl.ARRAY_BUFFER,o.nb);gl.enableVertexAttribArray(aN);gl.vertexAttribPointer(aN,3,gl.FLOAT,false,0,0);
  gl.uniform3fv(uC,o.color);gl.drawArrays(gl.TRIANGLES,0,o.count);}
 requestAnimationFrame(draw);
}

// ── pointer controls: orbit / pinch-zoom / two-finger-pan ──
var pts={},n0=0,pinch0=0,mid0=null;
function pcount(){return Object.keys(pts).length;}
function midpt(){var xs=0,ys=0,k=0;for(var id in pts){xs+=pts[id].x;ys+=pts[id].y;k++;}return[xs/k,ys/k];}
function pdist(){var a=[];for(var id in pts)a.push(pts[id]);if(a.length<2)return 0;return Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);}
function flagInteract(){if(!interacted){interacted=true;var tp=$("tip");if(tp)tp.style.opacity=0;}}

cv.addEventListener("pointerdown",function(e){cv.setPointerCapture(e.pointerId);
 pts[e.pointerId]={x:e.clientX,y:e.clientY};flagInteract();
 if(pcount()===2){pinch0=pdist();mid0=midpt();}});
cv.addEventListener("pointermove",function(e){if(!pts[e.pointerId])return;
 var pv=pts[e.pointerId];var dx=e.clientX-pv.x,dy=e.clientY-pv.y;
 pts[e.pointerId]={x:e.clientX,y:e.clientY};
 if(pcount()>=2){
   var d=pdist();if(pinch0>0&&d>0){cam.r*=pinch0/d;cam.r=Math.max(diag*0.12,Math.min(diag*8,cam.r));pinch0=d;}
   var m=midpt();if(mid0){pan(m[0]-mid0[0],m[1]-mid0[1]);}mid0=m;
 }else{
   cam.az-=dx*0.01;cam.el+=dy*0.01;
   var lim=1.55;cam.el=Math.max(-lim,Math.min(lim,cam.el));
 }});
function endp(e){delete pts[e.pointerId];if(pcount()<2){mid0=null;pinch0=0;}}
cv.addEventListener("pointerup",endp);cv.addEventListener("pointercancel",endp);
cv.addEventListener("wheel",function(e){e.preventDefault();flagInteract();
 cam.r*=(1+(e.deltaY>0?0.1:-0.1));cam.r=Math.max(diag*0.12,Math.min(diag*8,cam.r));},{passive:false});
function pan(dx,dy){var eye=eyePos();var fwd=nrm(sub([cam.tx,cam.ty,cam.tz],eye));
 var right=nrm(cross(fwd,[0,0,1]));var up=cross(right,fwd);
 var k=cam.r*0.0016;
 cam.tx+=(-right[0]*dx+up[0]*dy)*k;cam.ty+=(-right[1]*dx+up[1]*dy)*k;cam.tz+=(-right[2]*dx+up[2]*dy)*k;}

// ── HUD + buttons ──
$("ttl").textContent=SCENE.title||"scene";
var st=SCENE.stats||{};
$("sub").textContent=(st.objects||objs.length)+" object(s) · "+(st.triangles||0).toLocaleString()+" tris"+(st.decimated?" (preview-decimated)":"");
$("spin").addEventListener("click",function(){spin=!spin;this.classList.toggle("on",spin);if(spin)interacted=false;});
$("reset").addEventListener("click",function(){cam={az:R0.az,el:R0.el,r:R0.r,tx:R0.tx,ty:R0.ty,tz:R0.tz};interacted=false;spin=true;$("spin").classList.add("on");});
if(SCENE.render){var sb=$("mode"),img=$("shot");img.src=SCENE.render;sb.style.display="";
 var rendered=false;sb.addEventListener("click",function(){rendered=!rendered;
  img.style.display=rendered?"block":"none";cv.style.display=rendered?"none":"block";
  sb.textContent=rendered?"3D":"Rendered";sb.classList.toggle("on",rendered);});}

window.addEventListener("resize",resize);
if(gl)requestAnimationFrame(draw);
</script></body></html>"""
